import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n >= 100) {
                out.print(0);
                return;
            }

            int[][] v = new int[5][105];
            for (int i = 1; i <= n; i++) {
                v[0][i] = in.nextInt();
                v[1][i] = in.nextInt();
                v[2][i] = in.nextInt();
                v[3][i] = in.nextInt();
                v[4][i] = in.nextInt();
            }

            boolean[] bad = new boolean[105];

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        if (i == j || j == k || k == i) {
                            continue;
                        }

                        long ax = v[0][j] - v[0][i];
                        long bx = v[1][j] - v[1][i];
                        long cx = v[2][j] - v[2][i];
                        long dx = v[3][j] - v[3][i];
                        long ex = v[4][j] - v[4][i];

                        long ay = v[0][k] - v[0][i];
                        long by = v[1][k] - v[1][i];
                        long cy = v[2][k] - v[2][i];
                        long dy = v[3][k] - v[3][i];
                        long ey = v[4][k] - v[4][i];

                        double val = ax * ay + bx * by + cx * cy + dx * dy + ex * ey;
                        long m1 = ax * ax + bx * bx + cx * cx + dx * dx + ex * ex;
                        long m2 = ay * ay + by * by + cy * cy + dy * dy + ey * ey;
                        val = val / Math.sqrt(m1);
                        val = val / Math.sqrt(m2);

                        if (Math.toDegrees(Math.acos(val)) + 0.000000001 < 90) {
                            bad[i] = true;
                        }
                    }
                }
            }

            int cnt = 0;
            for (int i = 1; i <= n; i++) {
                if (!bad[i]) cnt++;
            }

            out.println(cnt);
            for (int i = 1; i <= n; i++) {
                if (!bad[i]) out.println(i);
            }
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
